                          <AgentStorePage />
                        </Suspense>
                      </ErrorBoundary>
                    }
                  />
                  <Route
                    path="/usage"
                    element={
                      <ErrorBoundary>
                        <Suspense fallback={LOADING_FALLBACK}>
                          <UsagePage />
                        </Suspense>
                      </ErrorBoundary>
                    }
                  />
                </Routes>
              </WorkspaceGuard>
            </AuthGuard>
          </ServerProfileGuard>
        </BrowserRouter>
      </AndroidChromeInputPolicyProvider>
    </EncryptProvider>
  );
}

