import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import type { DesktopClientContext, KeyInventory, KnownScopesInput, OpenClientResult, ScopeActivation, SshForwardError, SshForwardEventHint, SshForwardHost, SshForwardHostEvent, SshForwardProfile, SshForwardSnapshot, WireCounter } from "@dam-hopper/ui/lib/ssh-forward-host";
import { incrementWireCounter, parseWireCounter } from "@dam-hopper/ui/lib/ssh-forward-host";

export const NATIVE_SSH_FORWARD_COMMANDS = {
  openClient: "ssh_forward_open_client", activateScope: "ssh_forward_activate_scope", snapshot: "ssh_forward_snapshot",
  createProfile: "ssh_forward_create_profile", updateProfile: "ssh_forward_update_profile", deleteProfile: "ssh_forward_delete_profile",
  start: "ssh_forward_start", stop: "ssh_forward_stop", restart: "ssh_forward_restart", listKeys: "ssh_forward_list_keys",
  approveHost: "ssh_forward_approve_host", purgeScope: "ssh_forward_purge_scope",
} as const satisfies Record<Exclude<keyof SshForwardHost, "subscribe" | "dispose">, string>;

function isDesktop(platform: string, enabled: boolean): boolean { return enabled && ["windows", "macos", "linux"].includes(platform); }
function unavailable(): SshForwardError { return { code: "IPC_UNAVAILABLE", message: "Native SSH forwarding is temporarily unavailable.", retryable: true }; }
function parseError(value: unknown): SshForwardError { return value && typeof value === "object" && typeof (value as { code?: unknown }).code === "string" ? value as SshForwardError : unavailable(); }

export class NativeSshForwardHost implements SshForwardHost {
  private context: DesktopClientContext | null = null;
  private activationToken: WireCounter | null = null;
  private scopeId: string | null = null;
  private scopeGeneration: WireCounter | null = null;
  private snapshotState: SshForwardSnapshot | null = null;
  private operation = 0;
  private readonly listeners = new Set<(event: SshForwardHostEvent) => void>();
  private unlisten: UnlistenFn | null = null;
  private listening: Promise<void> | null = null;
  private disposed = false;

  async openClient(knownScopes: KnownScopesInput): Promise<OpenClientResult> {
    await this.installListener();
    const result = await this.call<OpenClientResult>(NATIVE_SSH_FORWARD_COMMANDS.openClient, { input: { knownScopes } });
    if (!result.context || !parseWireCounter(result.context.clientEpoch) || !parseWireCounter(result.activationTokenFloor)) throw unavailable();
    this.context = result.context; this.activationToken = result.activationTokenFloor; this.scopeId = result.activeScopeId; this.scopeGeneration = result.scopeGeneration; this.snapshotState = null;
    return result;
  }
  async activateScope(scopeId: string | null): Promise<ScopeActivation> {
    if (!this.context || !this.activationToken) throw unavailable();
    const token = incrementWireCounter(this.activationToken); if (!token) throw { ...unavailable(), code: "COUNTER_EXHAUSTED" as const };
    const operation = ++this.operation; const context = this.context; this.activationToken = token; this.scopeId = scopeId; this.snapshotState = null;
    try {
      const result = await this.call<ScopeActivation>(NATIVE_SSH_FORWARD_COMMANDS.activateScope, { input: { context, activationToken: token, scopeId } });
      if (operation !== this.operation || result.context.clientEpoch !== context.clientEpoch || result.activationToken !== token || result.scopeId !== scopeId) return result;
      this.scopeGeneration = result.scopeGeneration; this.snapshotState = result.snapshot; return result;
    } catch (error) { if (parseError(error).code === "ACTIVATION_SUPERSEDED") throw error; throw error; }
  }
  snapshot(): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.snapshot, {}); }
  createProfile(profile: SshForwardProfile): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.createProfile, { profile }); }
  updateProfile(profileId: string, expectedGeneration: WireCounter, profile: SshForwardProfile): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.updateProfile, { profileId, expectedGeneration, profile }); }
  deleteProfile(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.deleteProfile, { profileId, expectedGeneration }); }
  start(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.start, { profileId, expectedGeneration }); }
  stop(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.stop, { profileId, expectedGeneration }); }
  restart(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.restart, { profileId, expectedGeneration }); }
  listKeys(): Promise<KeyInventory> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.listKeys, {}); }
  approveHost(profileId: string, expectedGeneration: WireCounter, challengeId: string, algorithm: string, fingerprint: string): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.approveHost, { profileId, expectedGeneration, challengeId, algorithm, fingerprint }); }
  async purgeScope(scopeId: string, knownScopes: KnownScopesInput): Promise<{ scopeId: string; purged: boolean }> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.purgeScope, { scopeId, knownScopes }); }
  subscribe(listener: (event: SshForwardHostEvent) => void): () => void { this.listeners.add(listener); return () => this.listeners.delete(listener); }
  dispose(): void { if (this.disposed) return; this.disposed = true; ++this.operation; this.unlisten?.(); this.unlisten = null; }
  private async command<T>(command: string, extra: object): Promise<T> {
    if (!this.context || !this.activationToken || !this.scopeId || !this.scopeGeneration) throw unavailable();
    const result = await this.call<T>(command, { input: { context: this.context, activationToken: this.activationToken, scopeId: this.scopeId, scopeGeneration: this.scopeGeneration, ...this.snapshotState && { expectedProfilesRevision: this.snapshotState.profilesRevision, expectedTrustRevision: this.snapshotState.trustRevision }, ...extra } });
    if (this.isSnapshot(result)) this.snapshotState = result; return result;
  }
  private isSnapshot(value: unknown): value is SshForwardSnapshot { return Boolean(value && typeof value === "object" && "profilesRevision" in value); }
  private async call<T>(command: string, input: object): Promise<T> { try { return await invoke<T>(command, input); } catch (error) { throw parseError(error); } }
  private async installListener(): Promise<void> { if (this.listening) return this.listening; this.listening = listen<SshForwardEventHint>("ssh-forward:changed", (event) => this.handleHint(event.payload)).then((unlisten) => { if (this.disposed) unlisten(); else this.unlisten = unlisten; }); return this.listening; }
  private handleHint(hint: SshForwardEventHint): void {
    const context = this.context;
    if (!context || hint.desktopInstanceId !== context.desktopInstanceId || hint.managerSessionId !== context.managerSessionId || hint.clientEpoch !== context.clientEpoch || hint.activationToken !== this.activationToken || hint.scopeId !== this.scopeId) return;
    if (![hint.scopeGeneration, hint.profilesRevision, hint.trustRevision].every(parseWireCounter)) return;
    for (const listener of this.listeners) listener({ type: "changed", hint });
  }
}
export function createNativeSshForwardHost(platform: string, enabled = true): NativeSshForwardHost | null { return isDesktop(platform, enabled) ? new NativeSshForwardHost() : null; }

