import { useCallback, useEffect, useState } from "react";
import { useSshForwardHost } from "@/contexts/SshForwardHostContext.js";
import type { SshForwardSnapshot } from "@/lib/ssh-forward-host.js";

/** Maintains only native-authoritative forwarding snapshots; browser hosts do nothing. */
export function useSshForward() {
  const { host } = useSshForwardHost();
  const [snapshot, setSnapshot] = useState<SshForwardSnapshot | null>(null);
  const [error, setError] = useState<unknown>(null);
  const refresh = useCallback(async () => {
    if (!host) return null;
    try { const next = await host.snapshot(); setSnapshot(next); setError(null); return next; }
    catch (nextError) { setError(nextError); return null; }
  }, [host]);
  useEffect(() => {
    if (!host) { setSnapshot(null); return; }
    const unsubscribe = host.subscribe(() => { void refresh(); });
    return unsubscribe;
  }, [host, refresh]);
  return { snapshot, error, refresh };
}

